<template><div class="page"><div class="toolbar"><h2>告警管理</h2><el-button @click="load">刷新</el-button></div><PageTable title="告警列表" :rows="rows" :columns="columns" :total="total" :page="page" :loading="loading" @page-change="changePage"><template #rowActions="{row}"><el-button size="small" type="primary" :disabled="row.status!=='OPEN'" @click="toOrder(row)">生成工单</el-button><el-button size="small" type="success" :disabled="row.status!=='OPEN'" @click="handle(row)">标记处理</el-button><el-button size="small" type="danger" @click="remove(row)">删除</el-button></template></PageTable></div></template>
<script setup lang="ts">
import { onMounted,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import PageTable from '@/components/common/PageTable.vue';import { createWorkOrderFromAlarm,deleteAlarm,handleAlarm,listAlarms } from '@/api/alarm'
const rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false);const columns=[{prop:'title',label:'标题'},{prop:'alarmType',label:'类型'},{prop:'alarmLevel',label:'等级'},{prop:'status',label:'状态'},{prop:'createdAt',label:'发生时间'}];const load=async()=>{loading.value=true;try{const r:any=await listAlarms({page:page.value,size:10});rows.value=r.data.records;total.value=r.data.total}finally{loading.value=false}};const changePage=(v:number)=>{page.value=v;load()};const handle=async(r:any)=>{await handleAlarm(r.id);ElMessage.success('告警已标记为处理');load()};const toOrder=async(r:any)=>{const result:any=await createWorkOrderFromAlarm(r.id);ElMessage.success(`已生成工单 #${result.data.id}`);load()};const remove=async(r:any)=>{await ElMessageBox.confirm(`确认删除告警“${r.title}”？`,'删除确认',{type:'warning'});await deleteAlarm(r.id);ElMessage.success('已删除');load()};onMounted(load)
</script>
